    ok = True
    qty = None
    if len(parts) != 3 or parts[0] not in ("add", "remove"):
        ok = False
    else:
        op, sku, qs = parts
        try:
            qty = int(qs)
        except ValueError:
            ok = False
    if not ok or qty < 0:
        print(f"line {n}: malformed, rejected: {raw!r}")
        rejected.append(n)
        continue
    if op == "add":
        inv[sku] = inv.get(sku, 0) + qty
    else:
        if sku not in inv or inv[sku] - qty < 0:
            print(f"line {n}: rejected: {raw!r}")
            rejected.append(n)
        else:
            inv[sku] -= qty

with open("inventory_after.json", "w", encoding="utf-8") as f:
